value.string:
{
 "additionalProperties": false,
 "required": ["script_id"],
 "type": "object",
 "properties": {
 "body": {"default": null, "type": ["string", "null"], "description": "Python body (or pass body_file instead). REQUIRED to update an existing script; a call without it is refused so a call meant as an erp5_skin_call can never silently empty a script (session issue B6). Writing an explicitly empty body ('') needs allow_empty=true."},
 "skin_folder": {"default": "custom", "type": "string", "description": "Skin folder."},
 "title": {"default": "", "type": "string", "description": "Title."},
 "allow_overwrite_core": {"default": false, "type": ["boolean", "integer"], "description": "Allow core overwrite."},
 "allow_empty": {"default": false, "type": ["boolean", "integer"], "description": "Only for an explicit wipe together with body='': allow writing an empty body over an existing script."},
 "params": {"default": "", "type": "string", "description": "Parameter signature."},
 "live_test": {"default": false, "type": ["boolean", "integer"], "description": "Write-then-verify: after writing, immediately call the script and attach the result. A live-test failure does not abort the write."},
 "script_id": {"type": "string", "description": "Script id."},
 "body_file": {"default": null, "type": ["string", "null"], "description": "Read the full body from this server-reachable local path instead of passing body; the response sha256/length let you verify byte-exact deployment against the local file."}
 }
 }
